{% set print_style = frappe.db.get_single_value("Print Settings", "print_style") %}
{% set color = frappe.db.get_value("Print Style", print_style, "custom_color") %}
<style>
    .pf-color {
        color: {{ color }};
    }

    .pf-item-table {
        width: 100%;
        border-collapse: collapse;
        margin-top: 10px;
        font-size: 12px;
    }

    .pf-item-table th,
    .pf-item-table td {
        border: 1px solid {{ color }};
        padding: 2 2 !important;
        vertical-align: top;
    }

    .pf-item-table thead th {
        background-color: {{ color }};
        color: #fff;
        text-align: center;
        font-weight: 600;
    }

    .pf-item-table tbody tr:nth-child(even) {
        background-color: #f9f9f9;
    }

    .pf-item-idx,
    .pf-item-qty,
    .pf-item-wh {
        text-align: center;
        white-space: nowrap;
    }

    .pf-item-barcode {
        text-align: center;
        font-family: monospace;
        font-size: 11px;
    }

    .pf-item-name {
        font-weight: 600;
        display: block;
        margin-bottom: 2px;
    }

    .pf-item-desc {
        font-size: 11px;
        color: #555;
    }
</style>


<div class="pf-font">
    
    {% if letter_head %}
        {{ letter_head }}
    {% endif %}
    
    <!-- TITLE BASED ON ENTRY TYPE -->
    <h3 class="pf-heading pf-color">{{ doc.stock_entry_type }}</h3>
    
    <table class="pf-font-size" style="width: 100%; line-height: 1;">
        <tbody>

            <tr>
                <td style="width: 40%; padding-left: 20px!important;"></td>
                <td class="pf-color" style="width: 30%; text-align: right;">
                    <p>Document Ref رقم المستند</p>
                </td>
                <td style="width: 30%; text-align: right;">
                    <p>{{ doc.name }}</p>
                </td>
            </tr>

            <tr>
                <td style="width: 40%; padding-left: 20px!important;"></td>
                <td class="pf-color" style="width: 30%; text-align: right;">
                    <p>Posting Date تاريخ الإدخال</p>
                </td>
                <td style="width: 30%; text-align: right;">
                    <p>{{ doc.get_formatted("posting_date") }}</p>
                </td>
            </tr>

        </tbody>
    </table>
    
    <!-- ITEM TABLE WITH BARCODE -->
<table class="pf-item-table pf-font-size">
    <thead>
        <tr>
            <th style="width: 5%;">No.<br>م</th>
            <th style="width: 15%;">Barcode<br>الباركود</th>
            <th style="width: 30%;">Name<br>الاسم</th>
            <th style="width: 20%;">QTY / UOM<br>الكمية / الوحدة</th>
            <th style="width: 15%;">Source WH<br>مخزن المصدر</th>
            <th style="width: 15%;">Target WH<br>مخزن الوجهة</th>
        </tr>
    </thead>
    <tbody>
        {% for item in doc.items %}
            <tr>
                <!-- INDEX -->
                <td class="pf-item-idx">
                    {{ item.idx }}
                </td>

                <!-- BARCODE -->
                <td class="pf-item-barcode">
                    {% set bc = frappe.db.get_value("Item Barcode", {"parent": item.item_code, "uom": item.uom}, "barcode") %}
                    {% if not bc %}
                        {% set bc = frappe.db.get_value("Item Barcode", {"parent": item.item_code}, "barcode") %}
                    {% endif %}
                    {{ bc or "" }}
                </td>

                <!-- NAME -->
                <td>
                    <span class="pf-item-name">{{ item.item_name }}</span>
                </td>

                <!-- QTY / UOM -->
                <td class="pf-item-qty">
                    {{ item.qty }} {{ item.uom }}
                </td>

                <!-- SOURCE WAREHOUSE -->
                <td class="pf-item-wh">
                    {{ item.s_warehouse or "" }}
                </td>

                <!-- TARGET WAREHOUSE -->
                <td class="pf-item-wh">
                    {{ item.t_warehouse or "" }}
                </td>
            </tr>
        {% endfor %}
    </tbody>
</table>

    
    <table class="pf-font-size" style="width: 100%; margin-top: 10px;">
        <tr>
            <td rowspan="3" style="width: 25%;">
                <img src="https://api.qrserver.com/v1/create-qr-code/?data={{ doc.name }}&size=120x120">
            </td>

            <td style="width: 12%;"></td>

            <td style="width: 33%;">
                {% if doc.project %}
                    Project Name المشروع:
                {% endif %}
            </td>

            <td style="width: 30%;">
                {% if doc.project %}
                    {{ frappe.db.get_value("Project", doc.project, "project_name") }}
                {% endif %}
            </td>
        </tr>
    </table>
    
    {% if doc.remarks %}
        <div class="pf-terms pf-font-size">
            <p><strong class="pf-color">Remarks</strong></p>
            <br>
            <p>{{ doc.remarks }}</p>
        </div>
    {% endif %}
    
    {% if footer %}
        <div class="text-center footer small">
            {{ footer }}
        </div>
    {% endif %}
    
</div>

{% set workflow_signatures = get_workflow_signatures_for_print(doc.doctype, doc.name) %}

<h4>Workflow Approvals</h4>

{% if workflow_signatures and workflow_signatures|length > 0 %}
<table border="1" cellpadding="5" cellspacing="0" style="width:100%; border-collapse: collapse; margin-top:10px;">
    <tr style="background:#f2f2f2;">
        <th>Step</th>
        <th>Approved By</th>
        <th>Email</th>
        <th>Date</th>
        <th>Signature</th>
    </tr>
    {% for step in workflow_signatures %}
    <tr>
        <td>{{ step.workflow_state }}</td>
        <td>{{ step.user }}</td>
        <td>{{ step.email }}</td>
        <td>{{ step.timestamp }}</td>
        <td style="text-align:center;">
            {% if step.signature %}
                <img src="{{ step.signature }}" style="max-width:100px;">
            {% else %}
                <span>No Signature</span>
            {% endif %}
        </td>
    </tr>
    {% endfor %}
</table>
{% else %}
<p><strong>No workflow signatures found.</strong></p>
{% endif %}
